<?php require dirname(__DIR__).'/core/bootstrap.php';$u=auth(true);$admin=true;$error='';if(is_post()){verify_csrf();try{$vals=['company'=>input('company',120),'contact_email'=>input('contact_email',190),'whatsapp'=>input('whatsapp',15),'announcement'=>input('announcement',3000),'privacy_contact'=>input('privacy_contact',190)];if(!$vals['company']||!filter_var($vals['contact_email'],FILTER_VALIDATE_EMAIL)||!filter_var($vals['privacy_contact'],FILTER_VALIDATE_EMAIL))throw new InvalidArgumentException('Empresa e e-mails válidos são obrigatórios.');if($vals['whatsapp']!==''&&!preg_match('/^\d{10,15}$/',$vals['whatsapp']))throw new InvalidArgumentException('WhatsApp deve conter apenas números com DDI e DDD.');db()->beginTransaction();foreach($vals as $k=>$v)run('UPDATE settings SET value=? WHERE name=?',[$v,$k]);audit('configuracoes_atualizadas');db()->commit();flash('Configurações salvas.');go('admin/configuracoes.php');}catch(InvalidArgumentException $ex){if(db()->inTransaction())db()->rollBack();$error=$ex->getMessage();}}require ROOT.'/includes/panel.php';?><h1>Configurações.</h1><?php if($error):?><div class="errors"><?=e($error)?></div><?php endif;?><form method="post"><?php csrf();foreach(['company'=>'Nome da empresa','contact_email'=>'E-mail comercial','whatsapp'=>'WhatsApp: DDI + DDD + número','privacy_contact'=>'E-mail de privacidade'] as $k=>$v):?><label class="field"><?=$v?><input name="<?=$k?>" value="<?=e(setting($k))?>" maxlength="<?=$k==='whatsapp'?15:190?>"></label><?php endforeach;?><label class="field">Comunicado da central<textarea name="announcement" maxlength="3000"><?=e(setting('announcement'))?></textarea></label><button class="primary">Salvar configurações</button></form><?php require ROOT.'/includes/endpanel.php';?>
